ValidationRule.errorConditionFormula:
AND(
    $Profile.Name = "Customer Community Plus Login User",
    ISCHANGED(Status),
    NOT(
        OR(
            AND(TEXT(PRIORVALUE(Status)) = "Draft", TEXT(Status) = "Submitted"),
            AND(TEXT(PRIORVALUE(Status)) = "Changes Requested", TEXT(Status) = "Changes Completed")
        )
    )
)
